(()=>{const API='/api/creator_tools.php',CSRF=document.querySelector('meta[name="csrf-token"]')?.content||'',STORE='evruni_creator_v5',defaults={lang:'ru',target:'English',blur:18,overlay:92,alertText:'💰 Донат +500 ₽ · Спасибо!',alertDuration:4};const $=s=>document.querySelector(s),screen=$('#screen'),video=$('#video');let stream=null,mic=null,ws=null,identified=false,seq=0,reqs=new Map(),events=0;const tools=[['🎙️','Voice Cleaner','Локальное шумоподавление микрофона.','mic'],['💬','AI Chat Bot','Ответ зрителю по событию.','chat'],['🛡️','AI Moderator','Проверка сообщения без фонового сканирования.','moderation'],['🎨','Chat Overlay','Чат поверх предпросмотра.','overlay'],['🔔','Smart Alerts','Донат, подписка или raid локально.','alerts'],['🌍','Live Translator','Перевод выбранной реплики.','translator'],['🔞','Content Censor','Blur предпросмотра.','censor'],['✂️','Auto Clips','Лёгкая отметка момента.','clips'],['🧠','Stream Copilot','Подсказка на событие.','copilot'],['📊','Stream Analytics','Статистика текущей сессии.','analytics'],['📝','Stream Summary','Summary завершённого стрима.','summary'],['📱','Shorts Maker','Hook/title/caption/hashtags.','shorts']];const state=Object.fromEntries(tools.map(x=>[x[3],false]));function log(t){events++;$('#count').textContent=events+' событий';const d=document.createElement('div');d.textContent=new Date().toLocaleTimeString()+' — '+t;$('#log').prepend(d)}function setRun(c,on){const b=c.querySelector('.run');c.classList.toggle('on',on);b.classList.toggle('running',on);b.textContent=on?'● Запущено':'▶ Запустить';c.querySelector('.state').textContent=on?'● Запущено':'○ Выключено'}function done(c,text='✓ Выполнено'){if(!c)return;const b=c.querySelector('.run');b.classList.add('done');b.textContent=text;setTimeout(()=>{b.classList.remove('done');b.textContent='▶ Запустить'},1800)}function panel(t){const x={mic:'<div class="field"><label>Шумоподавление</label><select><option>Высокое</option><option>Среднее</option><option>Низкое</option></select></div>',chat:'<div class="field"><label>Стиль ответа</label><select><option>Дружелюбный</option><option>Короткий</option><option>Энергичный</option></select></div>',moderation:'<div class="field"><label>Строгость</label><select><option>Средняя</option><option>Мягкая</option><option>Строгая</option></select></div>',overlay:'<div class="field"><label>Прозрачность</label><input type="range" min="30" max="100" value="92"></div>',alerts:'<div class="field"><label>Событие</label><select><option>Донат</option><option>Подписка</option><option>Raid</option></select></div>',translator:'<div class="field"><label>Язык</label><select><option>English</option><option>Russian</option><option>German</option><option>Spanish</option></select></div>',censor:'<div class="field"><label>Blur</label><input type="range" min="0" max="32" value="18"></div>',clips:'<div class="field"><label>Название</label><input placeholder="Момент стрима"></div>',copilot:'<div class="field"><label>Режим</label><select><option>Краткая подсказка</option><option>Следующее действие</option></select></div>',analytics:'<div class="status">Счётчики остаются в браузере.</div>',summary:'<div class="field"><label>Заметки</label><textarea placeholder="Ключевые моменты стрима…"></textarea></div>',shorts:'<div class="field"><label>Момент</label><textarea placeholder="Что произошло…"></textarea></div>'};return x[t]||''}function render(){const root=$('#tools');root.innerHTML='';tools.forEach(([ic,name,desc,t])=>{const c=document.createElement('article');c.className='card';c.dataset.type=t;c.innerHTML='<div class="icon">'+ic+'</div><h3>'+name+'</h3><p>'+desc+'</p><div class="bar"><span class="status state">○ Выключено</span><button class="mini setup">⚙ Настроить</button></div><div class="panel">'+panel(t)+'</div><button class="btn run">▶ Запустить</button>';root.appendChild(c);c.querySelector('.setup').onclick=()=>{document.querySelectorAll('.card.open').forEach(x=>{if(x!==c)x.classList.remove('open')});c.classList.toggle('open')};c.querySelector('.run').onclick=()=>run(c,t)})}async function run(c,t){if(t==='mic'){if(state.mic){mic?.getTracks().forEach(x=>x.stop());mic=null;state.mic=false;setRun(c,false);log('Voice Cleaner остановлен');return}try{mic=await navigator.mediaDevices.getUserMedia({audio:{noiseSuppression:true,echoCancellation:true,autoGainControl:true}});state.mic=true;setRun(c,true);log('Voice Cleaner запущен локально')}catch(e){log('Микрофон недоступен')}}else if(t==='overlay'){state.overlay=!state.overlay;screen.classList.toggle('chat',state.overlay);setRun(c,state.overlay);log('Chat Overlay '+(state.overlay?'запущен':'остановлен'))}else if(t==='alerts'){screen.classList.add('alert');$('#donate').textContent=$('#alertText').value;setTimeout(()=>screen.classList.remove('alert'),Number($('#alertDuration').value||4)*1000);done(c,'✓ Алерт показан');log('Smart Alert показан')}else if(t==='censor'){state.censor=!state.censor;screen.style.filter=state.censor?'blur('+$('#blurRange').value+'px)':'';setRun(c,state.censor);log('Content Censor '+(state.censor?'запущен':'остановлен'))}else if(t==='clips'){done(c);log('Момент отмечен')}else if(t==='analytics'){done(c);log('Analytics обновлена локально')}else{const a={chat:'chatbot',moderation:'moderate',translator:'translate',copilot:'copilot',summary:'summary',shorts:'shorts'}[t];if(a)await ai(a,$('#event').value.trim()||'Событие стрима',c)}}async function ai(action,text,c){$('#result').textContent='⏳ Выполняется…';try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({action,text,language:$('#lang').value,target_language:$('#target').value})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Ошибка');$('#result').textContent=d.result||d.message||'Готово';done(c);log('AI '+action+' выполнен')}catch(e){$('#result').textContent='Ошибка: '+e.message;log('AI '+action+' ошибка')}}document.querySelectorAll('.ai').forEach(b=>b.onclick=()=>ai(b.dataset.action,$('#event').value.trim()||'Новое событие',null));$('#share').onclick=async()=>{if(stream){stream.getTracks().forEach(x=>x.stop());stream=null;video.srcObject=null;screen.classList.remove('live');$('#share').textContent='▶ Запустить';log('Экран остановлен');return}try{stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});video.srcObject=stream;screen.classList.add('live');$('#share').textContent='● Запущено';stream.getVideoTracks()[0].onended=()=>$('#stop').click();log('Экран запущен локально')}catch(e){log('Демонстрация отменена')}};$('#stop').onclick=()=>$('#share').click();$('#blur').onclick=()=>{screen.style.filter=screen.style.filter?'':'blur('+$('#blurRange').value+'px)';$('#blur').classList.toggle('active');log('Blur переключён')};$('#overlay').onclick=()=>{screen.classList.toggle('chat');$('#overlay').classList.toggle('active');log('Overlay переключён')};$('#alert').onclick=()=>{screen.classList.add('alert');$('#donate').textContent=$('#alertText').value;setTimeout(()=>screen.classList.remove('alert'),Number($('#alertDuration').value||4)*1000);log('Тестовый донат')};$('#blurRange').oninput=e=>screen.style.setProperty('--blur',e.target.value+'px');$('#overlayRange').oninput=e=>document.documentElement.style.setProperty('--overlay',Number(e.target.value)/100);$('#save').onclick=()=>{localStorage.setItem(STORE,JSON.stringify({lang:$('#lang').value,target:$('#target').value,blur:+$('#blurRange').value,overlay:+$('#overlayRange').value,alertText:$('#alertText').value,alertDuration:+$('#alertDuration').value}));log('Настройки сохранены локально')};$('#reset').onclick=()=>{localStorage.removeItem(STORE);location.reload()};
async function sha(s){return new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))}function b64(a){let s='';a.forEach(x=>s+=String.fromCharCode(x));return btoa(s)}async function auth(pass,salt,challenge){const secret=b64(await sha(pass+salt));return b64(await sha(secret+challenge))}function obsStatus(t,on=false){$('#obsStatus').textContent=(on?'● ':'○ ')+t;$('#obsStatus').className='status'+(on?' on':'')}function send(type,data={}){if(!ws||!identified)throw new Error('OBS не подключён');const id='e'+(++seq)+'_'+Date.now();ws.send(JSON.stringify({op:6,d:{requestType:type,requestId:id,requestData:data}}));return new Promise((resolve,reject)=>reqs.set(id,{resolve,reject}))}async function connectOBS(){if(ws){ws.close();ws=null;identified=false;obsStatus('Не подключён');$('#obsConnect').textContent='Подключить OBS';return}const host=$('#obsHost').value.trim()||'127.0.0.1',port=$('#obsPort').value.trim()||'4455',pass=$('#obsPass').value;obsStatus('Подключение…');try{ws=new WebSocket('ws://'+host+':'+port,'obswebsocket.json');ws.onmessage=async e=>{const m=JSON.parse(e.data);if(m.op===0){const d=m.d||{},id={rpcVersion:1};if(d.authentication)id.authentication=await auth(pass,d.authentication.salt,d.authentication.challenge);ws.send(JSON.stringify({op:1,d:id}))}else if(m.op===2){identified=true;obsStatus('OBS подключён',true);$('#obsConnect').textContent='Отключить';log('OBS подключён');refreshScenes()}else if(m.op===7){const r=reqs.get(m.d.requestId);if(!r)return;reqs.delete(m.d.requestId);m.d.requestStatus.result?r.resolve(m.d.responseData||{}):r.reject(new Error(m.d.requestStatus.comment||'OBS ошибка'))}else if(m.op===5){const d=m.d||{},ed=d.eventData||{};if(d.eventType==='StreamStateChanged')obsStatus(ed.outputActive?'OBS: стрим запущен':'OBS: стрим остановлен',!!ed.outputActive);if(d.eventType==='CurrentProgramSceneChanged')log('OBS сцена: '+(ed.sceneName||''))}};ws.onerror=()=>{obsStatus('Ошибка соединения');log('OBS WebSocket ошибка')};ws.onclose=()=>{identified=false;ws=null;obsStatus('Соединение закрыто');$('#obsConnect').textContent='Подключить OBS'}}catch(e){obsStatus('Ошибка: '+e.message)}}async function refreshScenes(){try{const s=await send('GetSceneList'),cur=await send('GetCurrentProgramScene'),box=$('#obsScenesList');box.innerHTML='';(s.scenes||[]).forEach(sc=>{const b=document.createElement('button');b.className='mini scene'+(sc.sceneName===cur.sceneName?' active':'');b.textContent=sc.sceneName;b.onclick=async()=>{try{await send('SetCurrentProgramScene',{sceneName:sc.sceneName});document.querySelectorAll('.scene').forEach(x=>x.classList.remove('active'));b.classList.add('active');log('OBS сцена: '+sc.sceneName)}catch(e){log('OBS: '+e.message)}};box.appendChild(b)})}catch(e){log('OBS сцены: '+e.message)}}$('#obsConnect').onclick=connectOBS;$('#obsScenes').onclick=refreshScenes;document.querySelectorAll('.obsbtn').forEach(b=>b.onclick=async()=>{try{await send(b.dataset.req);b.classList.add('active');setTimeout(()=>b.classList.remove('active'),900);log('OBS: '+b.dataset.req)}catch(e){log('OBS: '+e.message)}});try{const x={...defaults,...JSON.parse(localStorage.getItem(STORE)||'{}')};$('#lang').value=x.lang;$('#target').value=x.target;$('#blurRange').value=x.blur;$('#overlayRange').value=x.overlay;$('#alertText').value=x.alertText;$('#alertDuration').value=x.alertDuration;$('#overlayRange').dispatchEvent(new Event('input'))}catch(e){}render();log('Creator Tools готовы')})();
</script></body></html>